import { GoogleGenAI } from "@google/genai";
import { TarotCard, Spread } from '../types';

export const interpretReading = async (
  question: string,
  spread: Spread,
  cards: { card: TarotCard; isReversed: boolean; positionName: string }[]
): Promise<string> => {
  // 每次请求重新初始化以确保获取最新 API Key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const cardDescriptions = cards.map(c => `
- 位置【${c.positionName}】: ${c.card.nameCn} (${c.isReversed ? '逆位' : '正位'})
  关键词: ${c.card.keywords.join(', ')}
  画面深度含义: ${c.card.description}
  元素属性: ${c.card.element || '未知'}`
  ).join('\n');

  const prompt = `
    你是一位资深的塔罗牌占卜师。请根据以下牌阵和问题进行解读。

    用户问题: "${question}"
    使用牌阵: "${spread.name}"

    抽牌结果:
    ${cardDescriptions}

    【解读质量守则（务必遵守）】
    - 保持你现在“温和、神秘”的气质与整体结构不变，但减少模板化措辞。
    - 禁止使用以下套路表达或同义句：如“宇宙告诉你/牌在提醒你/跟随内心/一切都会好起来/命运安排/能量很强/你需要相信自己”等空泛句。
    - 语言尽量具体：少形容词堆叠。充分结合提供的“画面深度含义”和“元素属性”来构建解读逻辑。

    目标效果：
    1. 杜绝“模板腔/套路句”，拒绝廉价的心灵鸡汤。
    2. 表现出“资深、见多识广”的专业解牌者特质，语气沉稳且带有深度洞察。
    3. 更有同理心，但保持客观中立，不给予虚假的希望。
    4. 逻辑清晰：把局势中的具体不确定性点出来，并给出具有可执行性的、清晰的行为建议。

    请提供包括每个位置的简要分析和最后的综合建议。
    请使用Markdown格式输出。
  `;

  try {
    const response = await ai.models.generateContent({
