import { UserProgress, DivinationResult, AIConfig } from '../types';

const KEYS = {
  PROGRESS: 'lumina_progress',
  HISTORY: 'lumina_history',
  NOTES: 'lumina_notes',
  SETTINGS: 'lumina_settings',
  ACTIVE_SESSION: 'lumina_active_session',
  AI_CONFIG: 'lumina_ai_configs'
};

const INITIAL_PROGRESS: UserProgress = {
  learnedCards: [],
  dailyDraw: { date: '', cardId: null, isReversed: false, note: '' },
  streak: 0,
  lastLogin: ''
};

export const initStorage = async () => {
  if (navigator.storage && navigator.storage.persist) {
    try {
      const isPersisted = await navigator.storage.persisted();
      if (!isPersisted) {
        await navigator.storage.persist();
      }
    } catch (e) {
      console.warn("Storage persistence request failed", e);
    }
  }
};

export const getProgress = (): UserProgress => {
  try {
    const stored = localStorage.getItem(KEYS.PROGRESS);
    return stored ? JSON.parse(stored) : INITIAL_PROGRESS;
  } catch (e) {
    return INITIAL_PROGRESS;
  }
};

export const saveProgress = (progress: UserProgress) => {
  localStorage.setItem(KEYS.PROGRESS, JSON.stringify(progress));
};

export const getHistory = (): DivinationResult[] => {
  try {
    const stored = localStorage.getItem(KEYS.HISTORY);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    return [];
  }
};

export const saveHistory = (record: DivinationResult) => {
  const history = getHistory();
  history.unshift(record);
  localStorage.setItem(KEYS.HISTORY, JSON.stringify(history));
};

export const deleteHistoryItem = (id: string) => {
  const history = getHistory();
  const newHistory = history.filter(item => item.id !== id);
  localStorage.setItem(KEYS.HISTORY, JSON.stringify(newHistory));
};

// --- AI Configuration Persistence ---

export const getAIConfigs = (): AIConfig[] => {
  try {
    const stored = localStorage.getItem(KEYS.AI_CONFIG);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    return [];
  }
};

export const saveAIConfigs = (configs: AIConfig[]) => {
  localStorage.setItem(KEYS.AI_CONFIG, JSON.stringify(configs));
};

export const getActiveAIConfig = (): AIConfig | null => {
  const configs = getAIConfigs();
  return configs.find(c => c.isActive) || null;
};

// --- Active Session Management ---

export const saveActiveSession = (data: any) => {
  localStorage.setItem(KEYS.ACTIVE_SESSION, JSON.stringify(data));
};

export const getActiveSession = (): any | null => {
  try {
    const stored = localStorage.getItem(KEYS.ACTIVE_SESSION);
    return stored ? JSON.parse(stored) : null;
  } catch (e) {
    return null;
  }
};

export const clearActiveSession = () => {
  localStorage.removeItem(KEYS.ACTIVE_SESSION);
};

export const getNote = (cardId: number): string => {
  try {
    const notes = JSON.parse(localStorage.getItem(KEYS.NOTES) || '{}');
    return notes[cardId] || '';
  } catch (e) {
    return '';
  }
};

export const saveNote = (cardId: number, content: string) => {
  try {
    const notes = JSON.parse(localStorage.getItem(KEYS.NOTES) || '{}');
    notes[cardId] = content;
    localStorage.setItem(KEYS.NOTES, JSON.stringify(notes));
  } catch (e) {
    console.error("Failed to save note", e);
  }
};

import { GoogleGenAI } from "@google/genai";
import { TarotCard, Spread, AIConfig } from '../types';
import { getActiveAIConfig } from './storage';

/**
 * 核心解读方法：根据配置选择不同的服务商
 */
export const interpretReading = async (
  question: string,
  spread: Spread,
  cards: { card: TarotCard; isReversed: boolean; positionName: string }[]
): Promise<string> => {
  const config = getActiveAIConfig();

  const cardDescriptions = cards.map(c => 
    `- 位置【${c.positionName}】: ${c.card.nameCn} (${c.isReversed ? '逆位' : '正位'})
  关键词: ${c.card.keywords.join(', ')}
  深度含义: ${c.card.description}
  元素属性: ${c.card.element || '未知'}`
  ).join('\n');

  const prompt = `
    你是一位资深的塔罗牌占卜师。请根据以下牌阵和问题进行解读。

    用户问题: "${question}"
    使用牌阵: "${spread.name}"

    抽牌结果:
    ${cardDescriptions}

    请提供一个富有洞察力、语气温和且神秘的解读。包括每个位置的简要分析和最后的综合建议。
    请使用Markdown格式输出。
  `;

  // 如果没有配置，默认使用环境中的 Gemini 密钥
  if (!config || config.provider === 'google') {
    return callGemini(prompt, config?.apiKey, config?.model);
  }

  // 根据提供商调用相应接口
  switch (config.provider) {
    case 'openai':
    case 'deepseek':
      return callOpenAICompatible(prompt, config);
    case 'anthropic':
      return callAnthropic(prompt, config);
    default:
      return callGemini(prompt, config.apiKey, config.model);
  }
};

/**
 * 支持追问的对话逻辑
 */
export const continueReading = async (
  history: { role: 'user' | 'model', parts: { text: string }[] }[]
): Promise<string> => {
  const config = getActiveAIConfig();

  // 目前仅 Gemini 通过 SDK 提供便捷的 Chat 状态管理，其他暂用全量上下文
  if (!config || config.provider === 'google') {
    const ai = new GoogleGenAI({ apiKey: config?.apiKey || process.env.API_KEY || '' });
    const chat = ai.chats.create({
      model: config?.model || 'gemini-3-flash-preview',
      history: history.slice(0, -1),
    });
    const response = await chat.sendMessage({ message: history[history.length - 1].parts[0].text });
    return response.text || "未能获取启示。";
  }

  // 对非 Google 提供商采用简单重试逻辑
  const lastUserMsg = history[history.length - 1].parts[0].text;
  const contextPrompt = `基于之前的塔罗牌解读，用户追问道：${lastUserMsg}\n请继续以资深占卜师的身份回答。`;
  return interpretReading(contextPrompt, { name: '追问', id: 'follow-up', positions: [], description: '' }, []);
};

/**
 * 测试连接方法
 */
export const testConnection = async (config: AIConfig): Promise<boolean> => {
  try {
    if (config.provider === 'google') {
      const ai = new GoogleGenAI({ apiKey: config.apiKey || process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: config.model || 'gemini-3-flash-preview',
        contents: "Hi",
      });
      return !!response.text;
    }

    const res = await fetch(config.baseUrl || getBaseUrl(config.provider), {
      method: 'POST',
      headers: getHeaders(config),
      body: JSON.stringify(getPayload("Hello", config))
    });
    return res.ok;
  } catch (e) {
    console.error("Connection test failed:", e);
    return false;
  }
};

// --- 私有辅助方法 ---

async function callGemini(prompt: string, apiKey?: string, model?: string) {
  const ai = new GoogleGenAI({ apiKey: apiKey || process.env.API_KEY || '' });
  const response = await ai.models.generateContent({
    model: model || 'gemini-3-flash-preview',
    contents: prompt,
  });
  return response.text || "解读感应中断。";
}

async function callOpenAICompatible(prompt: string, config: AIConfig) {
  const url = config.baseUrl || (config.provider === 'openai' ? 'https://api.openai.com/v1/chat/completions' : 'https://api.deepseek.com/chat/completions');
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${config.apiKey}`
    },
    body: JSON.stringify({
      model: config.model,
      messages: [{ role: "user", content: prompt }]
    })
  });
  const data = await response.json();
  return data.choices?.[0]?.message?.content || "服务商返回异常。";
}

async function callAnthropic(prompt: string, config: AIConfig) {
  const response = await fetch(config.baseUrl || 'https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': config.apiKey,
      'anthropic-version': '2023-06-01',
      'dangerously-allow-browser': 'true' // 注意：前端直接调用可能存在 CORS 限制
    },
    body: JSON.stringify({
      model: config.model,
      max_tokens: 2000,
      messages: [{ role: "user", content: prompt }]
    })
  });
  const data = await response.json();
  return data.content?.[0]?.text || "Claude 感应中断。";
}

function getBaseUrl(provider: string) {
  if (provider === 'openai') return 'https://api.openai.com/v1/chat/completions';
  if (provider === 'deepseek') return 'https://api.deepseek.com/chat/completions';
  if (provider === 'anthropic') return 'https://api.anthropic.com/v1/messages';
  return '';
}

function getHeaders(config: AIConfig) {
  const headers: any = { 'Content-Type': 'application/json' };
  if (config.provider === 'openai' || config.provider === 'deepseek') {
    headers['Authorization'] = `Bearer ${config.apiKey}`;
  } else if (config.provider === 'anthropic') {
    headers['x-api-key'] = config.apiKey;
    headers['anthropic-version'] = '2023-06-01';
  }
  return headers;
}

function getPayload(prompt: string, config: AIConfig) {
  if (config.provider === 'anthropic') {
    return { model: config.model, max_tokens: 10, messages: [{ role: "user", content: prompt }] };
  }
  return { model: config.model, messages: [{ role: "user", content: prompt }] };
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { spreads, tarotDeck, getCardImageUrl } from '../constants';
