    CheckCircle2, AlertCircle, Database, Cpu
} from 'lucide-react';

interface ChatMessage {
    role: 'user' | 'model';
    parts: { text: string }[];
}

const shuffleArray = (array: number[]) => {
    const newArray = [...array];
    for (let i = newArray.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
    }
    return newArray;
};

const Divination: React.FC = () => {
  const [step, setStep] = useState<'select' | 'input' | 'drawing' | 'result'>('select');
  const [selectedSpread, setSelectedSpread] = useState<Spread | null>(null);
  const [question, setQuestion] = useState('');
  const [isProtocolsOpen, setIsProtocolsOpen] = useState(false);
  const [isApiSettingsOpen, setIsApiSettingsOpen] = useState(false);

  // AI Config State
  const [aiConfigs, setAiConfigs] = useState<AIConfig[]>([]);
  const [editingConfig, setEditingConfig] = useState<Partial<AIConfig>>({ provider: 'google', isActive: true });
  const [isTesting, setIsTesting] = useState(false);
  const [testResult, setTestResult] = useState<'success' | 'error' | null>(null);

  const [shuffledDeck, setShuffledDeck] = useState<number[]>([]);
  const [pickedIndices, setPickedIndices] = useState<{cardId: number, isReversed: boolean, deckIndex?: number}[]>([]);
  const [drawnCards, setDrawnCards] = useState<{cardId: number, isReversed: boolean, positionId: number}[]>([]);
  const [revealedIndices, setRevealedIndices] = useState<number[]>([]);
  const [aiInterpretation, setAiInterpretation] = useState('');
  const [isLoadingAI, setIsLoadingAI] = useState(false);
  const [detailedCard, setDetailedCard] = useState<TarotCard | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [followUpText, setFollowUpText] = useState('');
  const [isSendingFollowUp, setIsSendingFollowUp] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const [isHydrated, setIsHydrated] = useState(false);

  useEffect(() => {
    const configs = getAIConfigs();
    setAiConfigs(configs);
    const active = configs.find(c => c.isActive);
    if (active) setEditingConfig(active);

    const saved = getActiveSession();
    if (saved) {
      setStep(saved.step || 'select');
      if (saved.selectedSpreadId) {
        const spread = spreads.find(s => s.id === saved.selectedSpreadId);
        setSelectedSpread(spread || null);
      }
      setQuestion(saved.question || '');
      setPickedIndices(saved.pickedIndices || []);
      setDrawnCards(saved.drawnCards || []);
      setRevealedIndices(saved.revealedIndices || []);
      setAiInterpretation(saved.aiInterpretation || '');
      setChatHistory(saved.chatHistory || []);
      setShuffledDeck(saved.shuffledDeck || []);
    }
    setIsHydrated(true); 
  }, []);

  useEffect(() => {
    if (!isHydrated) return;
    if (step === 'select') {
      clearActiveSession();
    } else {
      saveActiveSession({
        step, selectedSpreadId: selectedSpread?.id, question,
        pickedIndices, drawnCards, revealedIndices,
        aiInterpretation, chatHistory, shuffledDeck 
      });
    }
  }, [isHydrated, step, selectedSpread, question, pickedIndices, drawnCards, revealedIndices, aiInterpretation, chatHistory, shuffledDeck]);

  const handleSpreadSelect = (spread: Spread) => {
    setSelectedSpread(spread);
    setStep('input');
  };

  const handleSaveConfig = () => {
    const newConfigs = aiConfigs.filter(c => c.provider !== editingConfig.provider);
    const finalConfig = { ...editingConfig, isActive: true } as AIConfig;
    // 设置当前为唯一激活项
    const updatedConfigs = [...newConfigs.map(c => ({ ...c, isActive: false })), finalConfig];
    setAiConfigs(updatedConfigs);
    saveAIConfigs(updatedConfigs);
    setTestResult(null);
    setIsApiSettingsOpen(false);
  };

  const handleTestConnection = async () => {
    setIsTesting(true);
    setTestResult(null);
    const success = await testConnection(editingConfig as AIConfig);
    setTestResult(success ? 'success' : 'error');
    setIsTesting(false);
  };

  const startDrawing = () => {
    if (!question.trim()) return;
    setShuffledDeck(shuffleArray(Array.from({ length: 78 }, (_, i) => i)));
    setPickedIndices([]);
    setStep('drawing');
  };

  const handlePickCard = (deckIndex: number, actualCardId: number) => {
    if (!selectedSpread || pickedIndices.length >= selectedSpread.positions.length) return;
    if (pickedIndices.some((p: any) => p.deckIndex === deckIndex)) return;

    const isReversed = Math.random() > 0.5;
    const newPicks = [...pickedIndices, { cardId: actualCardId, isReversed, deckIndex }];
    setPickedIndices(newPicks);

    if (newPicks.length === selectedSpread.positions.length) {
        setTimeout(() => {
            setDrawnCards(newPicks.map((pick, i) => ({
                cardId: pick.cardId,
                isReversed: pick.isReversed,
                positionId: selectedSpread.positions[i].id
            })));
            setStep('result');
            setRevealedIndices([]);
