                    </div>
                    <h3 className="text-xl font-serif text-white mb-3 group-hover:text-mystic-gold transition-colors">{spread.name}</h3>
                    <p className="text-slate-400 text-sm leading-relaxed font-light">{spread.description}</p>
                </div>
