              <div onClick={(e) => e.stopPropagation()} className="bg-mystic-950 w-full max-w-xl rounded-[3rem] border border-white/10 p-10 relative shadow-[0_0_100px_rgba(109,40,217,0.2)]">
                  <button onClick={() => setIsApiSettingsOpen(false)} className="absolute top-8 right-8 text-slate-500 hover:text-white"><X size={24} /></button>

                  <div className="text-center mb-8">
                      <Settings2 className="text-mystic-gold mx-auto mb-4" size={40} />
                      <h2 className="text-2xl font-serif text-white uppercase tracking-widest">多模型接入中心</h2>
                      <p className="text-slate-500 text-[10px] uppercase tracking-widest mt-2">Divine AI Management</p>
                  </div>

                  <div className="space-y-6">
                      <div className="grid grid-cols-2 gap-4">
                          {(['google', 'openai', 'anthropic', 'deepseek'] as AIProvider[]).map(p => (
                              <button 
                                key={p} 
                                onClick={() => setEditingConfig({ ...editingConfig, provider: p, baseUrl: undefined })}
                                className={`p-4 rounded-2xl border transition-all text-xs font-bold uppercase tracking-widest ${editingConfig.provider === p ? 'bg-mystic-gold/10 border-mystic-gold text-mystic-gold' : 'bg-white/5 border-white/5 text-slate-500 hover:border-white/20'}`}
                              >
                                  {p}
                              </button>
                          ))}
                      </div>

                      <div className="space-y-4">
                          <div className="space-y-2">
                              <label className="text-[10px] text-slate-500 uppercase tracking-widest ml-1 font-bold">API Key / 密钥</label>
                              <input 
                                  type="password" 
                                  value={editingConfig.apiKey || ''} 
                                  onChange={(e) => setEditingConfig({ ...editingConfig, apiKey: e.target.value })}
                                  placeholder={editingConfig.provider === 'google' ? "留空则使用环境默认密钥" : "输入您的个人 API Key"}
                                  className="w-full bg-black/40 border border-white/10 p-4 rounded-xl text-white text-sm focus:border-mystic-gold/50 outline-none"
                              />
                          </div>
                          <div className="grid grid-cols-2 gap-4">
                              <div className="space-y-2">
                                  <label className="text-[10px] text-slate-500 uppercase tracking-widest ml-1 font-bold">Model / 模型 ID</label>
                                  <input 
                                      type="text" 
                                      value={editingConfig.model || ''} 
                                      onChange={(e) => setEditingConfig({ ...editingConfig, model: e.target.value })}
                                      placeholder="e.g. gpt-4o, gemini-3-pro"
                                      className="w-full bg-black/40 border border-white/10 p-4 rounded-xl text-white text-sm focus:border-mystic-gold/50 outline-none"
                                  />
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[10px] text-slate-500 uppercase tracking-widest ml-1 font-bold">Custom Endpoint (可选)</label>
                                  <input 
                                      type="text" 
                                      value={editingConfig.baseUrl || ''} 
                                      onChange={(e) => setEditingConfig({ ...editingConfig, baseUrl: e.target.value })}
                                      placeholder="自定义 API 地址"
                                      className="w-full bg-black/40 border border-white/10 p-4 rounded-xl text-white text-sm focus:border-mystic-gold/50 outline-none"
                                  />
                              </div>
                          </div>
                      </div>

                      <div className="flex gap-4 pt-4">
                          <button 
                            onClick={handleTestConnection}
                            disabled={isTesting || (!editingConfig.apiKey && editingConfig.provider !== 'google')}
                            className="flex-1 py-4 bg-white/5 border border-white/10 text-slate-400 rounded-xl font-bold text-[10px] uppercase hover:bg-white/10 transition flex items-center justify-center gap-2"
                          >
                              {isTesting ? <RefreshCw className="animate-spin" size={14}/> : <Activity size={14}/>}
                              测试连接
                          </button>
                          <button 
                            onClick={handleSaveConfig}
                            className="flex-[2] py-4 bg-mystic-gold text-mystic-950 rounded-xl font-bold text-[10px] uppercase shadow-lg shadow-mystic-gold/20"
                          >
                              激活并保存配置
                          </button>
                      </div>

                      {testResult && (
                          <div className={`p-4 rounded-xl border flex items-center gap-3 animate-flip-in ${testResult === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'}`}>
                              {testResult === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
                              <span className="text-xs font-bold uppercase tracking-wider">{testResult === 'success' ? '连接成功！服务商响应正常' : '连接失败：请检查密钥或地址'}</span>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Divination;

import { UserProgress, DivinationResult, AIConfig } from '../types';

const KEYS = {
  PROGRESS: 'lumina_progress',
  HISTORY: 'lumina_history',
  NOTES: 'lumina_notes',
  SETTINGS: 'lumina_settings',
  ACTIVE_SESSION: 'lumina_active_session',
  AI_CONFIG: 'lumina_ai_configs'
};

const INITIAL_PROGRESS: UserProgress = {
  learnedCards: [],
  dailyDraw: { date: '', cardId: null, isReversed: false, note: '' },
  streak: 0,
  lastLogin: ''
};

export const initStorage = async () => {
  if (navigator.storage && navigator.storage.persist) {
    try {
      const isPersisted = await navigator.storage.persisted();
      if (!isPersisted) {
        await navigator.storage.persist();
      }
    } catch (e) {
      console.warn("Storage persistence request failed", e);
    }
  }
};

export const getProgress = (): UserProgress => {
  try {
    const stored = localStorage.getItem(KEYS.PROGRESS);
    return stored ? JSON.parse(stored) : INITIAL_PROGRESS;
  } catch (e) {
    return INITIAL_PROGRESS;
  }
};

export const saveProgress = (progress: UserProgress) => {
  localStorage.setItem(KEYS.PROGRESS, JSON.stringify(progress));
};

export const getHistory = (): DivinationResult[] => {
  try {
    const stored = localStorage.getItem(KEYS.HISTORY);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    return [];
  }
};

export const saveHistory = (record: DivinationResult) => {
  const history = getHistory();
  history.unshift(record);
  localStorage.setItem(KEYS.HISTORY, JSON.stringify(history));
};

export const deleteHistoryItem = (id: string) => {
  const history = getHistory();
  const newHistory = history.filter(item => item.id !== id);
  localStorage.setItem(KEYS.HISTORY, JSON.stringify(newHistory));
};

// --- AI Configuration Persistence ---

export const getAIConfigs = (): AIConfig[] => {
  try {
    const stored = localStorage.getItem(KEYS.AI_CONFIG);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    return [];
  }
};

export const saveAIConfigs = (configs: AIConfig[]) => {
  localStorage.setItem(KEYS.AI_CONFIG, JSON.stringify(configs));
};

export const getActiveAIConfig = (): AIConfig | null => {
  const configs = getAIConfigs();
  return configs.find(c => c.isActive) || null;
};

// --- Active Session Management ---

export const saveActiveSession = (data: any) => {
  localStorage.setItem(KEYS.ACTIVE_SESSION, JSON.stringify(data));
};

export const getActiveSession = (): any | null => {
  try {
    const stored = localStorage.getItem(KEYS.ACTIVE_SESSION);
    return stored ? JSON.parse(stored) : null;
  } catch (e) {
    return null;
  }
};

export const clearActiveSession = () => {
  localStorage.removeItem(KEYS.ACTIVE_SESSION);
};

export const getNote = (cardId: number): string => {
  try {
    const notes = JSON.parse(localStorage.getItem(KEYS.NOTES) || '{}');
    return notes[cardId] || '';
  } catch (e) {
    return '';
  }
};

export const saveNote = (cardId: number, content: string) => {
  try {
    const notes = JSON.parse(localStorage.getItem(KEYS.NOTES) || '{}');
    notes[cardId] = content;
    localStorage.setItem(KEYS.NOTES, JSON.stringify(notes));
  } catch (e) {
    console.error("Failed to save note", e);
  }
};

// --- Data Backup and Restore ---

/**
 * Fix: Added missing exportData function to back up all app-related localStorage data.
 */
export const exportData = () => {
  const data: Record<string, string | null> = {};
  Object.keys(localStorage).forEach(key => {
    if (key.startsWith('lumina_')) {
      data[key] = localStorage.getItem(key);
    }
  });
  const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `lumina_backup_${new Date().toISOString().split('T')[0]}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

/**
 * Fix: Added missing importData function to restore app data from a provided backup file.
 */
export const importData = async (file: File): Promise<void> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        Object.keys(data).forEach(key => {
          if (key.startsWith('lumina_')) {
            const value = data[key];
            if (typeof value === 'string') {
              localStorage.setItem(key, value);
            }
          }
        });
        resolve();
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = () => reject(new Error("File reading failed"));
    reader.readAsText(file);
  });
};
